-- Generated by model/lib/sql/generate.mjs. Loads Standard Cost IN from cells/Standard Cost IN.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "Standard Cost IN" SELECT coalesce(k0."SKU", error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE)
FROM read_csv('cells/Standard Cost IN.csv', header = true, all_varchar = true) c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
